steps.code:
SELECT nombre || ' ' || apellido AS cliente
FROM clientes
WHERE provincia_id = 7;

SELECT nombre || ': ₡' || precio AS etiqueta
FROM productos
WHERE categoria_id = 2;

SELECT nombre, UPPER(nombre), LOWER(nombre), LENGTH(nombre)
FROM provincias;

SELECT nombre, LENGTH(nombre) AS caracteres
FROM productos
WHERE LENGTH(nombre) > 30;

SELECT TRIM('   Heredia  ') AS sin_espacios,
       TRIM('--Cartago--', '-') AS sin_guiones,
       REPLACE('Café molido', 'molido', 'en grano') AS reemplazado;

SELECT telefono, REPLACE(telefono, '-', '') AS solo_numeros
FROM clientes
WHERE provincia_id = 2;

