steps.code:
SELECT COUNT(*) AS productos FROM productos;
SELECT COUNT(*) AS pedidos FROM pedidos;
SELECT COUNT(*) AS lineas FROM detalle_pedido;
SELECT COUNT(*) AS resenas FROM resenas;

SELECT COUNT(*) AS pedidos,
       COUNT(empleado_id) AS con_vendedor,
       COUNT(*) - COUNT(empleado_id) AS en_linea
FROM pedidos;

SELECT COUNT(*) FROM pedidos WHERE empleado_id IS NULL;

SELECT COUNT(DISTINCT cliente_id) AS clientes_que_compraron,
       COUNT(DISTINCT empleado_id) AS vendedores,
       COUNT(DISTINCT metodo_pago) AS metodos
FROM pedidos;

SELECT COUNT(DISTINCT producto_id) AS productos_vendidos FROM detalle_pedido;

SELECT MIN(precio), MAX(precio), AVG(precio), ROUND(AVG(precio), 2)
FROM productos;

SELECT MIN(precio), MAX(precio), ROUND(AVG(precio)) AS promedio
FROM productos
WHERE categoria_id = 7;

SELECT MIN(fecha) AS primer_pedido, MAX(fecha) AS ultimo_pedido FROM pedidos;

SELECT MIN(fecha_ingreso) AS mas_antiguo, MAX(fecha_ingreso) AS mas_reciente FROM empleados;

SELECT MIN(nombre), MAX(nombre) FROM productos;

SELECT ROUND(AVG((julianday('2026-09-30') - julianday(fecha_nacimiento)) / 365.25), 1) AS edad_promedio,
       COUNT(fecha_nacimiento) AS clientes_con_dato
FROM clientes;

SELECT COUNT(*) AS resenas, ROUND(AVG(calificacion), 2) AS promedio
FROM resenas
WHERE strftime('%Y', fecha) = '2025';

